mapper.select:
SELECT t.field_handler_id, u.field_name AS field_handler_name, COUNT(*) AS handled_count, IFNULL(ROUND(AVG(CASE WHEN t.field_status = 'FINISH' AND t.field_finish_time IS NOT NULL THEN TIMESTAMPDIFF(MICROSECOND, t.field_create_time, t.field_finish_time) END) / 1000), 0) AS avg_duration_ms FROM ( SELECT COALESCE(NULLIF(w.field_expect_handler_id, ''), w.field_handler_id) AS field_handler_id, e.field_status, e.field_create_time, e.field_finish_time FROM sys_process_audit_note an INNER JOIN sys_process_example_workitem w ON w.field_id = an.field_workitem_id INNER JOIN sys_process_example e ON e.field_id = an.field_example_id
an.field_handle_type = 'HANDLER_PASS' AND COALESCE(NULLIF(w.field_expect_handler_id, ''), w.field_handler_id) IS NOT NULL
) t LEFT JOIN sys_org_element u ON u.field_id = t.field_handler_id AND u.field_org_type = 3 GROUP BY t.field_handler_id ORDER BY handled_count DESC, t.field_handler_id ASC LIMIT #{topN}
